input.old_string:
/* PLAN 057, nya ?preview=-hookar för prisbron (§ ?preview=-hookar).
   #bro är en 'flow'-akt (samma mekanik som .case-bridge/#pris) - dess
   --sc-ps sätts redan av motorn, vi väntar bara in den. */
if (mode === 'pris-bro'){
  var broEl = document.getElementById('bro');
  if (broEl){
    broEl.scrollIntoView({ block:'start' });
    window.scrollBy(0, 0.35 * window.innerHeight);
    var broTries = 0;
    (function waitBro(){
      var ps = parseFloat(getComputedStyle(broEl).getPropertyValue('--sc-ps'));
      broTries++;
      if (broTries < 40 && (isNaN(ps) || ps < 0.55)) requestAnimationFrame(waitBro);
    })();
  }
}
if (mode === 'pris-bro-skarv'){
  var prisEl = document.getElementById('pris');
  if (prisEl){
    var top = prisEl.getBoundingClientRect().top + window.scrollY;
    window.scrollTo(0, top - 0.5 * window.innerHeight);
  }
}

