    (function waitBro(){
      var ps = parseFloat(getComputedStyle(broEl).getPropertyValue('--sc-ps'));
      broTries++;
      if (broTries < 40 && (isNaN(ps) || ps < 0.4)) requestAnimationFrame(waitBro);
    })();
  }
}
